#include "apps.h"
#include "app_stage_e.h"
#include "heap.h"
#include "fat32.h"
#include "rtc.h"
#include "keyboard.h"
#define ARC_MAX 8
#define ARC_PATH "/disk/Sanctum/calendar.db"
typedef struct{char title[40],meta[40];uint16_t minute;bool live;}arc_event_t;
typedef struct{arc_event_t e[ARC_MAX];int count,selected;char status[48];}arc_t;
static void arc_save(arc_t*s){if(!fat32_is_mounted()){se_copy(s->status,"Not saved - RAM only",48);return;}fat32_mkdir_p("/disk/Sanctum");char b[512];int n=0;for(int i=0;i<s->count;i++){b[n++]=(char)('0'+s->e[i].minute/600);b[n++]=(char)('0'+(s->e[i].minute/60)%10);b[n++]=':';b[n++]=(char)('0'+(s->e[i].minute%60)/10);b[n++]=(char)('0'+s->e[i].minute%10);b[n++]='|';for(int k=0;s->e[i].title[k]&&n<500;k++)b[n++]=s->e[i].title[k];b[n++]='\n';}fat32_save_file(ARC_PATH,b,n);se_copy(s->status,"calendar saved",48);}
static void arc_draw(window_t*w,const gfx_target_t*t){arc_t*s=w->user_data;const ui_runtime_theme_t*h=ui_theme_current();gfx_clear(t,h->canvas);se_header(t,"ARC - THE DAY AS ONE TURN","Arc",false);rtc_time_t r;rtc_read(&r);char tm[6]={(char)('0'+r.hour/10),(char)('0'+r.hour%10),':',(char)('0'+r.minute/10),(char)('0'+r.minute%10),0};int cx=330,cy=360;for(int rr=225;rr>95;rr-=64)gfx_stroke_rect(t,cx-rr,cy-rr,rr*2,rr*2,h->border);gfx_fill_round_rect(t,cx-98,cy-98,196,196,98,h->surface);se_text(t,cx-16,cy-50,"NOW",h->muted);gfx_draw_string_scaled(t,cx-68,cy-16,tm,h->ink,3);se_text(t,cx-48,cy+45,"45 min free",h->muted);for(int i=0;i<s->count;i++){int a=(s->e[i].minute%720)*255/720;int x=cx-180+(i%3)*170,y=cy+125+(i%2)*42;gfx_fill_rect_gradient(t,x,y,120,7,ui_sunset((uint8_t)a),h->accent_berry);}se_card(t,78,640,500,116,h->surface,h->border);se_text(t,102,666,"COMMITTED           OPEN             QUIET AFTER",h->muted);se_bold(t,102,702,"4 h 20 m           3 h 10 m          18:00",h->ink);se_progress(t,102,734,450,168,h->border,h->accent_berry);
int x=640,y=128;se_text(t,x,96,"day arc     week spiral     open bands",h->muted);for(int i=0;i<s->count;i++){se_card(t,x,y,w->width-x-72,76,h->surface,i==s->selected?h->accent_coral:h->border);gfx_fill_rect(t,x+20,y+20,4,38,ui_sunset((uint8_t)(i*38)));se_bold(t,x+40,y+18,s->e[i].title,h->ink);se_text(t,x+40,y+43,s->e[i].meta,h->muted);char ti[6]={(char)('0'+s->e[i].minute/600),(char)('0'+(s->e[i].minute/60)%10),':',(char)('0'+(s->e[i].minute%60)/10),(char)('0'+s->e[i].minute%10),0};se_text(t,w->width-122,y+28,ti,h->muted);y+=90;}se_card(t,x,y+12,w->width-x-72,84,h->surface,h->border);se_text(t,x+24,y+38,"OPEN BAND",h->muted);se_text(t,x+24,y+64,"A task dropped here becomes a commitment.",h->ink);se_text(t,78,w->height-34,s->status,h->accent_berry);}
static void arc_key(window_t*w,char c){arc_t*s=w->user_data;if(c==27){arc_save(s);se_close(w);return;}if(c==KBD_KEY_UP)s->selected=(s->selected+s->count-1)%s->count;else if(c==KBD_KEY_DOWN||c=='\t')s->selected=(s->selected+1)%s->count;else if(c=='a'||c=='A'){if(s->count<ARC_MAX){arc_event_t*e=&s->e[s->count++];se_copy(e->title,"New focus band",40);se_copy(e->meta,"personal - protected",40);rtc_time_t r;rtc_read(&r);e->minute=(uint16_t)(r.hour*60+r.minute+60);e->live=true;s->selected=s->count-1;}arc_save(s);}else if(c=='e'||c=='E'){se_copy(s->e[s->selected].title,"Edited focus band",40);arc_save(s);}else if(c=='d'||c=='D'){for(int i=s->selected;i<s->count-1;i++)s->e[i]=s->e[i+1];if(s->count>1)s->count--;if(s->selected>=s->count)s->selected=s->count-1;arc_save(s);}}
static void arc_click(window_t*w,int x,int y){arc_t*s=w->user_data;if(x>=640&&y>=128){int i=(y-128)/90;if(i>=0&&i<s->count)s->selected=i;}}
window_t* app_arc_open(void){arc_t*s=kmalloc(sizeof(*s));if(!s)return 0;s->count=6;s->selected=0;const char*n[6]={"Ignition standup","Facet grading","Deep block","Ring review","Quiet band opens","Resonance - Ignition EP"};const char*m[6]={"Prism team - console","with Ilse - gallery","no signals","decision needed","signals held until now","sound prism - personal"};int mins[6]={540,660,810,960,1020,1160};for(int i=0;i<6;i++){se_copy(s->e[i].title,n[i],40);se_copy(s->e[i].meta,m[i],40);s->e[i].minute=(uint16_t)mins[i];s->e[i].live=true;}se_copy(s->status,fat32_is_mounted()?"A add  E edit  D delete  Esc save":"Not saved - RAM only",48);window_t*w=se_workspace("Arc",arc_draw,arc_click,arc_key,s,false);if(!w)kfree(s);return w;}
